// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address ref, uint256 drugs) public {
        // Ensure contract is initialized
        vm.assume(c.initialized() == false);
        c.seedMarket(1000);

        // Setup a user with some kilos to produce drugs
        vm.prank(sender);
        c.getFreeKilo();

        // Warp time so some drugs are produced
        vm.warp(block.timestamp + 100);

        // Snapshot marketDrugs before collectDrugs
        uint256 before = c.marketDrugs();

        // Call collectDrugs with the ref
        vm.prank(sender);
        c.collectDrugs(ref);

        // After collectDrugs, marketDrugs must not have decreased
        assertTrue(c.marketDrugs() >= before);
    }
}

